CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(190) PRIMARY KEY, setting_value TEXT NULL);
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) UNIQUE, password VARCHAR(255), name VARCHAR(150), role VARCHAR(30) DEFAULT 'technician', active TINYINT DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS clients (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(190), contact_person VARCHAR(190) NULL, phone VARCHAR(60) NULL, email VARCHAR(190) NULL, address TEXT NULL, logo_path VARCHAR(255) NULL, notes TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS assets (id INT AUTO_INCREMENT PRIMARY KEY, client_id INT, name VARCHAR(190), type VARCHAR(100) NULL, brand VARCHAR(100) NULL, model VARCHAR(100) NULL, serial_number VARCHAR(150) NULL, location VARCHAR(190) NULL, status VARCHAR(30) DEFAULT 'active', notes TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX (client_id));
CREATE TABLE IF NOT EXISTS tickets (id INT AUTO_INCREMENT PRIMARY KEY, ticket_number VARCHAR(60) UNIQUE, client_id INT, subject VARCHAR(255), description TEXT NULL, priority VARCHAR(20) DEFAULT 'medium', status VARCHAR(30) DEFAULT 'new', visit_date DATE NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX (client_id), INDEX (status));
CREATE TABLE IF NOT EXISTS tasks (id INT AUTO_INCREMENT PRIMARY KEY, ticket_id INT, item VARCHAR(255), serial_number VARCHAR(150) NULL, complaint TEXT NULL, diagnosis TEXT NULL, action_taken TEXT NULL, recommendation TEXT NULL, status VARCHAR(30) DEFAULT 'new', scope VARCHAR(20) DEFAULT 'retainer', parts_cost DECIMAL(10,2) DEFAULT 0, labor_cost DECIMAL(10,2) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX (ticket_id));
CREATE TABLE IF NOT EXISTS task_photos (id INT AUTO_INCREMENT PRIMARY KEY, task_id INT, photo_path VARCHAR(255), label VARCHAR(60) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX (task_id));
CREATE TABLE IF NOT EXISTS signatures (id INT AUTO_INCREMENT PRIMARY KEY, ticket_id INT, signed_by_name VARCHAR(190), signature_path VARCHAR(255), verification_code VARCHAR(30), ip_address VARCHAR(60) NULL, signed_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX (ticket_id), INDEX (verification_code));
CREATE TABLE IF NOT EXISTS quotes (id INT AUTO_INCREMENT PRIMARY KEY, quote_number VARCHAR(60) UNIQUE, ticket_id INT NULL, client_id INT, subject VARCHAR(255), status VARCHAR(20) DEFAULT 'draft', total DECIMAL(10,2) DEFAULT 0, notes TEXT NULL, approved_at DATETIME NULL, approved_by VARCHAR(190) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX (client_id));
CREATE TABLE IF NOT EXISTS quote_items (id INT AUTO_INCREMENT PRIMARY KEY, quote_id INT, description TEXT, quantity DECIMAL(10,2) DEFAULT 1, unit_cost DECIMAL(10,2) DEFAULT 0, total_cost DECIMAL(10,2) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX (quote_id));
CREATE TABLE IF NOT EXISTS maintenance_schedules (id INT AUTO_INCREMENT PRIMARY KEY, client_id INT, asset_id INT NULL, name VARCHAR(190), description TEXT NULL, interval_days INT DEFAULT 30, last_run DATE NULL, next_run DATE NULL, active TINYINT DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS mail_log (id INT AUTO_INCREMENT PRIMARY KEY, recipients TEXT, subject VARCHAR(255), status VARCHAR(20), error TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_log (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, action VARCHAR(100), module VARCHAR(60) NULL, details TEXT NULL, ip_address VARCHAR(60) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS login_attempts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) NULL, ip_address VARCHAR(45) NOT NULL, attempted_at DATETIME NOT NULL, INDEX login_attempts_ip_time (ip_address, attempted_at));
CREATE TABLE IF NOT EXISTS document_templates (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, template_type VARCHAR(30) NOT NULL, name VARCHAR(120) NOT NULL, subject VARCHAR(255) NULL, body TEXT NULL, created_at DATETIME NULL, INDEX document_templates_type (template_type));
CREATE TABLE IF NOT EXISTS network_devices (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, client_id INT UNSIGNED NOT NULL, name VARCHAR(190) NOT NULL, device_type VARCHAR(40) NOT NULL, hostname VARCHAR(190) NULL, ip_address VARCHAR(45) NULL, mac_address VARCHAR(32) NULL, manufacturer VARCHAR(120) NULL, model VARCHAR(120) NULL, location VARCHAR(190) NULL, status VARCHAR(30) NOT NULL DEFAULT 'active', notes TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX network_devices_client (client_id), INDEX network_devices_ip (ip_address));
CREATE TABLE IF NOT EXISTS cameras (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, client_id INT UNSIGNED NOT NULL, network_device_id INT UNSIGNED NULL, name VARCHAR(190) NOT NULL, camera_type VARCHAR(40) NOT NULL DEFAULT 'ip', ip_address VARCHAR(45) NULL, location VARCHAR(190) NULL, recorder VARCHAR(190) NULL, channel_number VARCHAR(40) NULL, status VARCHAR(30) NOT NULL DEFAULT 'active', notes TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX cameras_client (client_id), INDEX cameras_device (network_device_id));
CREATE TABLE IF NOT EXISTS vault_credentials (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, client_id INT UNSIGNED NULL, network_device_id INT UNSIGNED NULL, label VARCHAR(190) NOT NULL, username VARCHAR(190) NULL, secret_ciphertext MEDIUMTEXT NOT NULL, notes TEXT NULL, created_by INT UNSIGNED NULL, created_at DATETIME NOT NULL, updated_at DATETIME NULL, INDEX vault_credentials_client (client_id), INDEX vault_credentials_device (network_device_id));
CREATE TABLE IF NOT EXISTS custom_forms (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(190) NOT NULL, description TEXT NULL, fields_json TEXT NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NULL, INDEX custom_forms_active (active));
CREATE TABLE IF NOT EXISTS form_submissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, form_id INT UNSIGNED NOT NULL, submitted_by INT UNSIGNED NULL, answers_json LONGTEXT NOT NULL, submitted_at DATETIME NOT NULL, INDEX form_submissions_form (form_id), INDEX form_submissions_date (submitted_at));
CREATE TABLE IF NOT EXISTS sequences (name VARCHAR(30) PRIMARY KEY, current_value BIGINT DEFAULT 0);
INSERT IGNORE INTO sequences (name, current_value) VALUES ('ticket',0), ('quote',0);